Brief:
Un potager en grille : échange deux légumes voisins pour aligner trois carottes. Pas de chrono, la partie se termine quand plus aucun échange n'est possible.

Plan:
{"gameType":"puzzle-board","input":"drag-follow","lang":"fr","loop":"Échange deux légumes voisins sur la grille pour aligner trois carottes ou plus et marquer des points. La partie se termine quand plus aucun échange possible ne crée d'alignement.","slug":"potager-malin","style":"paper-cut","title":"Potager Malin"}

Game source (line-numbered):
1| <!doctype html>
2| <html lang="fr">
3| <head>
4| <meta charset="utf-8">
5| <meta name="viewport" content="width=device-width, initial-scale=1">
6| <title>Potager Malin</title>
7| <style>
8|   html, body {
9|     margin: 0; padding: 0; width: 100%; height: 100%;
10|     background: #f4ecd8;
11|     overflow: hidden;
12|     touch-action: none;
13|     font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
14|   }
15|   #wrap {
16|     position: fixed; inset: 0;
17|     display: flex; align-items: center; justify-content: center;
18|   }
19|   canvas {
20|     display: block;
21|     touch-action: none;
22|   }
23| </style>
24| </head>
25| <body>
26| <div id="wrap">
27| <canvas id="game"></canvas>
28| </div>
29| <script>
30| // ---- Bridge helper (verbatim) ----
31| const CARTRIDGE = {
32|   send(type, payload = {}) {
33|     window.parent.postMessage(
34|       { source: "cartridge", v: 1, type, payload },
35|       "*",
36|     );
37|   },
38| };
39| 
40| window.addEventListener("message", (event) => {
41|   const data = event.data;
42|   if (!data || data.source !== "cartridge-host") return;
43|   if (data.type === "pause") paused = true;
44|   if (data.type === "resume") paused = false;
45|   if (data.type === "reset") backToTitle();
46| });
47| </script>
48| <script>
49| (function(){
50|   const canvas = document.getElementById('game');
51|   const ctx = canvas.getContext('2d');
52| 
53|   const PALETTE = {
54|     bg: '#f4ecd8',
55|     layer: '#e07a5f',
56|     accent: '#3d405b',
57|     highlight: '#81b29a'
58|   };
59| 
60|   // Vegetable colours (paper-cut style, distinct hues)
61|   const VEG_TYPES = [
62|     { name: 'carotte', color: '#e07a5f' },
63|     { name: 'chou', color: '#81b29a' },
64|     { name: 'aubergine', color: '#3d405b' },
65|     { name: 'radis', color: '#c44536' },
66|     { name: 'mais', color: '#f2cc8f' }
67|   ];
68|   const CARROT_INDEX = 0;
69| 
70|   let paused = false;
71|   let state = 'title'; // 'title', 'play', 'end'
72|   let dpr = Math.max(1, window.devicePixelRatio || 1);
73| 
74|   const GRID = 8;
75|   let cellSize = 0;
76|   let boardX = 0, boardY = 0, boardSize = 0;
77| 
78|   let grid = []; // grid[row][col] = {type, jitter}
79|   let score = 0;
80|   let moves = 0;
81|   let endReason = null;
82| 
83|   // animation state for swap/fall
84|   let animating = false;
85|   let animQueue = [];
86| 
87|   // jitter seed table for paper-cut look, stable per cell position
88|   function jitterFor(seedBase) {
89|     // deterministic pseudo-random jitter from seed
90|     function rnd(s) {
91|       const x = Math.sin(s) * 10000;
92|       return x - Math.floor(x);
93|     }
94|     const pts = [];
95|     for (let i = 0; i < 4; i++) {
96|       const jx = (rnd(seedBase * 13 + i * 7) - 0.5) * 3;
97|       const jy = (rnd(seedBase * 29 + i * 11) - 0.5) * 3;
98|       pts.push([jx, jy]);
99|     }
100|     return pts;
101|   }
102| 
103|   function resize() {
104|     dpr = Math.max(1, window.devicePixelRatio || 1);
105|     const w = window.innerWidth;
106|     const h = window.innerHeight;
107|     canvas.style.width = w + 'px';
108|     canvas.style.height = h + 'px';
109|     canvas.width = Math.round(w * dpr);
110|     canvas.height = Math.round(h * dpr);
111|     ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
112| 
113|     boardSize = Math.min(w, h) * 0.9;
114|     cellSize = boardSize / GRID;
115|     boardX = (w - boardSize) / 2;
116|     boardY = (h - boardSize) / 2;
117| 
118|     draw();
119|   }
120| 
121|   function randType(excludeMatch, r, c) {
122|     // avoid creating immediate 3-match on init
123|     let tries = 0;
124|     while (true) {
125|       const t = Math.floor(Math.random() * VEG_TYPES.length);
126|       if (tries > 30) return t;
127|       tries++;
128|       // check left two
129|       if (c >= 2 && grid[r][c-1] && grid[r][c-2] &&
130|           grid[r][c-1].type === t && grid[r][c-2].type === t) continue;
131|       if (r >= 2 && grid[r-1] && grid[r-2] &&
132|           grid[r-1][c] && grid[r-2][c] &&
133|           grid[r-1][c].type === t && grid[r-2][c].type === t) continue;
134|       return t;
135|     }
136|   }
137| 
138|   function makeCell(r, c) {
139|     return {
140|       type: randType(null, r, c),
141|       seed: (r * 97 + c * 131) + Math.random()*1000,
142|       offX: 0, offY: 0, // animation offsets in px
143|       scale: 1,
144|       alpha: 1
145|     };
146|   }
147| 
148|   function initGrid() {
149|     grid = [];
150|     for (let r = 0; r < GRID; r++) {
151|       grid.push([]);
152|       for (let c = 0; c < GRID; c++) {
153|         grid[r].push(makeCell(r, c));
154|       }
155|     }
156|     score = 0;
157|     moves = 0;
158|     animating = false;
159|     animQueue = [];
160|   }
161| 
162|   function cellCenter(r, c) {
163|     return {
164|       x: boardX + c * cellSize + cellSize / 2,
165|       y: boardY + r * cellSize + cellSize / 2
166|     };
167|   }
168| 
169|   function toCanvas(evt) {
170|     const rect = canvas.getBoundingClientRect();
171|     return {
172|       x: evt.clientX - rect.left,
173|       y: evt.clientY - rect.top
174|     };
175|   }
176| 
177|   function cellAt(pos) {
178|     const c = Math.floor((pos.x - boardX) / cellSize);
179|     const r = Math.floor((pos.y - boardY) / cellSize);
180|     if (r < 0 || r >= GRID || c < 0 || c >= GRID) return null;
181|     return { r, c };
182|   }
183| 
184|   // ---- Match detection ----
185|   function findMatches() {
186|     const matched = [];
187|     for (let r = 0; r < GRID; r++) matched.push(new Array(GRID).fill(false));
188| 
189|     // horizontal
190|     for (let r = 0; r < GRID; r++) {
191|       let runStart = 0;
192|       for (let c = 1; c <= GRID; c++) {
193|         const same = c < GRID && grid[r][c] && grid[r][runStart] &&
194|           grid[r][c].type === grid[r][runStart].type;
195|         if (!same) {
196|           if (c - runStart >= 3) {
197|             for (let k = runStart; k < c; k++) matched[r][k] = true;
198|           }
199|           runStart = c;
200|         }
201|       }
202|     }
203|     // vertical
204|     for (let c = 0; c < GRID; c++) {
205|       let runStart = 0;
206|       for (let r = 1; r <= GRID; r++) {
207|         const same = r < GRID && grid[r][c] && grid[runStart][c] &&
208|           grid[r][c].type === grid[runStart][c].type;
209|         if (!same) {
210|           if (r - runStart >= 3) {
211|             for (let k = runStart; k < r; k++) matched[k][c] = true;
212|           }
213|           runStart = r;
214|         }
215|       }
216|     }
217|     return matched;
218|   }
219| 
220|   function hasAnyMatch(matched) {
221|     for (let r = 0; r < GRID; r++)
222|       for (let c = 0; c < GRID; c++)
223|         if (matched[r][c]) return true;
224|     return false;
225|   }
226| 
227|   function countMatchScore(matched) {
228|     let count = 0;
229|     let carrotBonus = 0;
230|     for (let r = 0; r < GRID; r++)
231|       for (let c = 0; c < GRID; c++)
232|         if (matched[r][c]) {
233|           count++;
234|           if (grid[r][c].type === CARROT_INDEX) carrotBonus++;
235|         }
236|     return count * 10 + carrotBonus * 5;
237|   }
238| 
239|   function clearAndDrop(matched) {
240|     // remove matched
241|     for (let c = 0; c < GRID; c++) {
242|       let writeRow = GRID - 1;
243|       for (let r = GRID - 1; r >= 0; r--) {
244|         if (!matched[r][c]) {
245|           grid[writeRow][c] = grid[r][c];
246|           writeRow--;
247|         }
248|       }
249|       for (let r = writeRow; r >= 0; r--) {
250|         grid[r][c] = makeCell(r, c);
251|       }
252|     }
253|   }
254| 
255|   function swap(a, b) {
256|     const tmp = grid[a.r][a.c];
257|     grid[a.r][a.c] = grid[b.r][b.c];
258|     grid[b.r][b.c] = tmp;
259|   }
260| 
261|   function isAdjacent(a, b) {
262|     const dr = Math.abs(a.r - b.r);
263|     const dc = Math.abs(a.c - b.c);
264|     return (dr + dc) === 1;
265|   }
266| 
267|   function anyLegalMove() {
268|     for (let r = 0; r < GRID; r++) {
269|       for (let c = 0; c < GRID; c++) {
270|         // try right
271|         if (c + 1 < GRID) {
272|           swap({r,c}, {r, c: c+1});
273|           const m = findMatches();
274|           swap({r,c}, {r, c: c+1});
275|           if (hasAnyMatch(m)) return true;
276|         }
277|         // try down
278|         if (r + 1 < GRID) {
279|           swap({r,c}, {r: r+1, c});
280|           const m = findMatches();
281|           swap({r,c}, {r: r+1, c});
282|           if (hasAnyMatch(m)) return true;
283|         }
284|       }
285|     }
286|     return false;
287|   }
288| 
289|   function resolveMatchesCascade() {
290|     // resolve chain of matches, accumulate score, then check end conditions
291|     let matched = findMatches();
292|     if (!hasAnyMatch(matched)) return false;
293|     let gained = 0;
294|     while (hasAnyMatch(matched)) {
295|       gained += countMatchScore(matched);
296|       clearAndDrop(matched);
297|       matched = findMatches();
298|     }
299|     score += gained;
300|     CARTRIDGE.send('score', { value: score });
301|     return true;
302|   }
303| 
304|   // ---- Input handling (drag-follow style) ----
305|   let dragStart = null; // {r,c}
306|   let dragCurrent = null; // canvas pos
307|   let dragOffset = { x: 0, y: 0 };
308|   let pointerId = null;
309|   let inputLocked = false;
310| 
311|   canvas.addEventListener('pointerdown', (event) => {
312|     if (state !== 'play' || paused || inputLocked) {
313|       if (state === 'title') {
314|         startGame();
315|       } else if (state === 'end') {
316|         // no restart via tap here; handled by reset command
317|       }
318|       return;
319|     }
320|     const pos = toCanvas(event);
321|     const cell = cellAt(pos);
322|     if (cell) {
323|       dragStart = cell;
324|       dragCurrent = pos;
325|       pointerId = event.pointerId;
326|       canvas.setPointerCapture(event.pointerId);
327|     }
328|   });
329| 
330|   canvas.addEventListener('pointermove', (event) => {
331|     if (dragStart && event.pointerId === pointerId) {
332|       dragCurrent = toCanvas(event);
333|       draw();
334|     }
335|   });
336| 
337|   function endDrag() {
338|     if (!dragStart || !dragCurrent) {
339|       dragStart = null; dragCurrent = null; pointerId = null;
340|       return;
341|     }
342|     const targetCell = cellAt(dragCurrent);
343|     if (targetCell && isAdjacent(dragStart, targetCell)) {
344|       attemptSwap(dragStart, targetCell);
345|     }
346|     dragStart = null;
347|     dragCurrent = null;
348|     pointerId = null;
349|     draw();
350|   }
351| 
352|   canvas.addEventListener('pointerup', endDrag);
353|   canvas.addEventListener('pointercancel', endDrag);
354| 
355|   function attemptSwap(a, b) {
356|     swap(a, b);
357|     const matched = findMatches();
358|     if (!hasAnyMatch(matched)) {
359|       // illegal move, revert
360|       swap(a, b);
361|       return;
362|     }
363|     inputLocked = true;
364|     moves += 1;
365|     resolveMatchesCascade();
366|     inputLocked = false;
367| 
368|     // check end conditions after resolving
369|     if (!anyLegalMove()) {
370|       state = 'end';
371|       endReason = 'stuck';
372|       CARTRIDGE.send('end', { reason: 'stuck', value: score });
373|     }
374|     draw();
375|   }
376| 
377|   // ---- Drawing ----
378|   function roundedPolyJitter(cx, cy, size, seed, color, shadow) {
379|     const half = size / 2;
380|     const r = size * 0.18;
381|     const pts = jitterFor(seed);
382|     ctx.save();
383|     if (shadow) {
384|       ctx.shadowColor = 'rgba(61,64,91,0.35)';
385|       ctx.shadowBlur = 6;
386|       ctx.shadowOffsetY = 3;
387|     }
388|     ctx.fillStyle = color;
389|     ctx.beginPath();
390|     const corners = [
391|       [cx - half, cy - half],
392|       [cx + half, cy - half],
393|       [cx + half, cy + half],
394|       [cx - half, cy + half]
395|     ];
396|     for (let i = 0; i < 4; i++) {
397|       const [px, py] = corners[i];
398|       const [jx, jy] = pts[i];
399|       const x = px + jx, y = py + jy;
400|       if (i === 0) ctx.moveTo(x + r, y);
401|       ctx.arcTo(x, y, corners[(i+1)%4][0], corners[(i+1)%4][1], r);
402|     }
403|     ctx.closePath();
404|     ctx.fill();
405|     ctx.restore();
406|   }
407| 
408|   function drawVeg(cx, cy, size, type, seed) {
409|     const veg = VEG_TYPES[type];
410|     // base plate (paper layer)
411|     roundedPolyJitter(cx, cy + 2, size * 0.92, seed, 'rgba(61,64,91,0.12)', false);
412|     roundedPolyJitter(cx, cy, size * 0.86, seed + 1, veg.color, true);
413| 
414|     // simple face/shape detail per veg to distinguish
415|     ctx.save();
416|     ctx.fillStyle = PALETTE.bg;
417|     ctx.globalAlpha = 0.85;
418|     const r = size * 0.09;
419|     if (type === CARROT_INDEX) {
420|       // carrot: triangle-ish highlight lines
421|       ctx.beginPath();
422|       ctx.moveTo(cx, cy - size*0.2);
423|       ctx.lineTo(cx - size*0.12, cy + size*0.18);
424|       ctx.lineTo(cx + size*0.12, cy + size*0.18);
425|       ctx.closePath();
426|       ctx.fillStyle = '#f4ecd8';
427|       ctx.globalAlpha = 0.5;
428|       ctx.fill();
429|     } else if (type === 1) {
430|       // chou: circles
431|       ctx.beginPath();
432|       ctx.arc(cx, cy, size*0.18, 0, Math.PI*2);
433|       ctx.fill();
434|     } else if (type === 2) {
435|       // aubergine: oval
436|       ctx.beginPath();
437|       ctx.ellipse(cx, cy, size*0.22, size*0.13, 0, 0, Math.PI*2);
438|       ctx.fill();
439|     } else if (type === 3) {
440|       // radis: small dot pair
441|       ctx.beginPath();
442|       ctx.arc(cx - size*0.1, cy, r*0.8, 0, Math.PI*2);
443|       ctx.arc(cx + size*0.1, cy, r*0.8, 0, Math.PI*2);
444|       ctx.fill();
445|     } else {
446|       // mais: grid dots
447|       for (let i = -1; i <= 1; i++) {
448|         for (let j = -1; j <= 1; j += 2) {
449|           ctx.beginPath();
450|           ctx.arc(cx + i*size*0.12, cy + j*size*0.1, r*0.5, 0, Math.PI*2);
451|           ctx.fill();
452|         }
453|       }
454|     }
455|     ctx.restore();
456|   }
457| 
458|   function drawBoardBackground() {
459|     // background card
460|     ctx.save();
461|     ctx.fillStyle = PALETTE.bg;
462|     ctx.fillRect(0, 0, canvas.width / dpr, canvas.height / dpr);
463|     ctx.restore();
464| 
465|     // board plate
466|     ctx.save();
467|     ctx.shadowColor = 'rgba(61,64,91,0.3)';
468|     ctx.shadowBlur = 8;
469|     ctx.shadowOffsetY = 4;
470|     ctx.fillStyle = PALETTE.layer;
471|     const pad = cellSize * 0.15;
472|     roundRect(ctx, boardX - pad, boardY - pad, boardSize + pad*2, boardSize + pad*2, 16);
473|     ctx.fill();
474|     ctx.restore();
475| 
476|     ctx.save();
477|     ctx.fillStyle = '#fffaf0';
478|     roundRect(ctx, boardX, boardY, boardSize, boardSize, 10);
479|     ctx.globalAlpha = 0.5;
480|     ctx.fill();
481|     ctx.restore();
482|   }
483| 
484|   function roundRect(ctx, x, y, w, h, r) {
485|     ctx.beginPath();
486|     ctx.moveTo(x + r, y);
487|     ctx.arcTo(x + w, y, x + w, y + h, r);
488|     ctx.arcTo(x + w, y + h, x, y + h, r);
489|     ctx.arcTo(x, y + h, x, y, r);
490|     ctx.arcTo(x, y, x + w, y, r);
491|     ctx.closePath();
492|   }
493| 
494|   function drawHUD() {
495|     const w = canvas.width / dpr;
496|     ctx.save();
497|     ctx.shadowColor = 'rgba(61,64,91,0.3)';
498|     ctx.shadowBlur = 6;
499|     ctx.shadowOffsetY = 3;
500|     ctx.fillStyle = PALETTE.highlight;
501|     roundRect(ctx, 12, 12, 160, 50, 12);
502|     ctx.fill();
503|     ctx.restore();
504| 
505|     ctx.fillStyle = PALETTE.accent;
506|     ctx.font = 'bold 22px -apple-system, Arial, sans-serif';
507|     ctx.textBaseline = 'middle';
508|     ctx.textAlign = 'left';
509|     ctx.fillText('Score: ' + score, 24, 37);
510|   }
511| 
512|   function drawTitle() {
513|     const w = canvas.width / dpr;
514|     const h = canvas.height / dpr;
515|     ctx.fillStyle = PALETTE.bg;
516|     ctx.fillRect(0, 0, w, h);
517| 
518|     // title plate
519|     ctx.save();
520|     ctx.shadowColor = 'rgba(61,64,91,0.3)';
521|     ctx.shadowBlur = 8;
522|     ctx.shadowOffsetY = 4;
523|     ctx.fillStyle = PALETTE.layer;
524|     const pw = Math.min(w * 0.85, 480);
525|     const ph = 220;
526|     const px = (w - pw) / 2;
527|     const py = (h - ph) / 2 - 40;
528|     roundRect(ctx, px, py, pw, ph, 20);
529|     ctx.fill();
530|     ctx.restore();
531| 
532|     ctx.fillStyle = PALETTE.bg;
533|     ctx.font = 'bold 32px -apple-system, Arial, sans-serif';
534|     ctx.textAlign = 'center';
535|     ctx.textBaseline = 'middle';
536|     ctx.fillText('Potager Malin', w/2, py + 60);
537| 
538|     ctx.font = '18px -apple-system, Arial, sans-serif';
539|     ctx.fillText('Échangez les légumes voisins', w/2, py + 110);
540|     ctx.fillText('pour aligner 3 carottes ou plus.', w/2, py + 135);
541| 
542|     // play button
543|     ctx.save();
544|     ctx.shadowColor = 'rgba(61,64,91,0.3)';
545|     ctx.shadowBlur = 6;
546|     ctx.shadowOffsetY = 3;
547|     ctx.fillStyle = PALETTE.highlight;
548|     const bw = 180, bh = 56;
549|     const bx = w/2 - bw/2, by = py + ph + 30;
550|     roundRect(ctx, bx, by, bw, bh, 14);
551|     ctx.fill();
552|     ctx.restore();
553| 
554|     ctx.fillStyle = PALETTE.accent;
555|     ctx.font = 'bold 22px -apple-system, Arial, sans-serif';
556|     ctx.fillText('Jouer', w/2, by + bh/2 + 2);
557| 
558|     titleButton = { x: bx, y: by, w: bw, h: bh };
559|   }
560| 
561|   let titleButton = null;
562| 
563|   function drawEnd() {
564|     const w = canvas.width / dpr;
565|     const h = canvas.height / dpr;
566|     drawBoard();
567|     drawHUD();
568| 
569|     ctx.save();
570|     ctx.fillStyle = 'rgba(61,64,91,0.55)';
571|     ctx.fillRect(0, 0, w, h);
572|     ctx.restore();
573| 
574|     ctx.save();
575|     ctx.shadowColor = 'rgba(61,64,91,0.3)';
576|     ctx.shadowBlur = 8;
577|     ctx.shadowOffsetY = 4;
578|     ctx.fillStyle = PALETTE.layer;
579|     const pw = Math.min(w * 0.8, 420);
580|     const ph = 180;
581|     const px = (w - pw) / 2;
582|     const py = (h - ph) / 2;
583|     roundRect(ctx, px, py, pw, ph, 18);
584|     ctx.fill();
585|     ctx.restore();
586| 
587|     ctx.fillStyle = PALETTE.bg;
588|     ctx.font = 'bold 26px -apple-system, Arial, sans-serif';
589|     ctx.textAlign = 'center';
590|     ctx.textBaseline = 'middle';
591|     const msg = endReason === 'win' ? 'Potager parfait !' : 'Plus aucun coup possible';
592|     ctx.fillText(msg, w/2, py + 55);
593| 
594|     ctx.font = '20px -apple-system, Arial, sans-serif';
595|     ctx.fillText('Score final : ' + score, w/2, py + 100);
596| 
597|     ctx.font = '15px -apple-system, Arial, sans-serif';
598|     ctx.fillText('(réinitialisation via l\'hôte)', w/2, py + 140);
599|   }
600| 
601|   function drawBoard() {
602|     drawBoardBackground();
603|     for (let r = 0; r < GRID; r++) {
604|       for (let c = 0; c < GRID; c++) {
605|         const cell = grid[r][c];
606|         if (!cell) continue;
607|         let center = cellCenter(r, c);
608|         let cx = center.x, cy = center.y;
609|         // if this cell is being dragged, offset toward pointer
610|         if (dragStart && dragStart.r === r && dragStart.c === c && dragCurrent) {
